CREATE TABLE `employees` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `report_to` bigint(20) unsigned DEFAULT NULL,
  `dashboard_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`dashboard_config`)),
  `nama` varchar(255) NOT NULL,
  `nik` varchar(255) NOT NULL,
  `tempat_lahir` varchar(255) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `alamat_tetap` text DEFAULT NULL,
  `alamat_sekarang` text DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `gender` enum('laki-laki','perempuan') DEFAULT NULL,
  `status_pernikahan` varchar(255) DEFAULT NULL,
  `pendidikan_terakhir` varchar(255) DEFAULT NULL,
  `agama` varchar(255) DEFAULT NULL,
  `no_telpon_1` varchar(255) DEFAULT NULL,
  `no_telpon_2` varchar(255) DEFAULT NULL,
  `photo` varchar(255) DEFAULT NULL,
  `signature` varchar(255) DEFAULT NULL,
  `face_descriptor` text DEFAULT NULL,
  `faceio_facial_id` varchar(255) DEFAULT NULL,
  `no_ktp` varchar(255) DEFAULT NULL,
  `npwp` varchar(255) DEFAULT NULL,
  `no_bpjs_ketenagakerjaan` varchar(255) DEFAULT NULL,
  `no_bpjs_kesehatan` varchar(255) DEFAULT NULL,
  `file_ktp` varchar(255) DEFAULT NULL,
  `file_npwp` varchar(255) DEFAULT NULL,
  `file_kk` varchar(255) DEFAULT NULL,
  `file_ijazah` varchar(255) DEFAULT NULL,
  `file_lainnya` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`file_lainnya`)),
  `department_id` bigint(20) unsigned NOT NULL,
  `position_id` bigint(20) unsigned NOT NULL,
  `work_location_id` bigint(20) unsigned DEFAULT NULL,
  `working_location_id` bigint(20) unsigned DEFAULT NULL,
  `shift_id` bigint(20) unsigned DEFAULT NULL,
  `status_kepegawaian` enum('tetap','kontrak','probation','magang') NOT NULL DEFAULT 'tetap',
  `hire_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `nama_bank` varchar(255) DEFAULT NULL,
  `cabang_bank` varchar(255) DEFAULT NULL,
  `no_rekening` varchar(255) DEFAULT NULL,
  `nama_rekening` varchar(255) DEFAULT NULL,
  `nama_kontak_darurat_1` varchar(255) DEFAULT NULL,
  `no_kontak_darurat_1` varchar(255) DEFAULT NULL,
  `nama_kontak_darurat_2` varchar(255) DEFAULT NULL,
  `no_kontak_darurat_2` varchar(255) DEFAULT NULL,
  `gaji_pokok` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tunjangan_jabatan` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tunjangan_kehadiran` decimal(15,2) NOT NULL DEFAULT 0.00,
  `tunjangan_transportasi` decimal(15,2) NOT NULL DEFAULT 0.00,
  `uang_makan` decimal(15,2) NOT NULL DEFAULT 0.00,
  `uang_lembur` decimal(15,2) NOT NULL DEFAULT 0.00,
  `thr` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gaji_bpjs_tk` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gaji_bpjs_jkn` decimal(15,2) NOT NULL DEFAULT 0.00,
  `gross_up` tinyint(1) NOT NULL DEFAULT 0,
  `pinjaman_koperasi` decimal(15,2) NOT NULL DEFAULT 0.00,
  `potongan_lain_1` decimal(15,2) NOT NULL DEFAULT 0.00,
  `potongan_lain_2` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `employees_nik_unique` (`nik`),
  KEY `employees_user_id_foreign` (`user_id`),
  KEY `employees_department_id_foreign` (`department_id`),
  KEY `employees_position_id_foreign` (`position_id`),
  KEY `employees_work_location_id_foreign` (`work_location_id`),
  KEY `employees_shift_id_foreign` (`shift_id`),
  KEY `employees_report_to_foreign` (`report_to`),
  KEY `employees_working_location_id_foreign` (`working_location_id`),
  CONSTRAINT `employees_department_id_foreign` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `employees_position_id_foreign` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`),
  CONSTRAINT `employees_report_to_foreign` FOREIGN KEY (`report_to`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `employees_shift_id_foreign` FOREIGN KEY (`shift_id`) REFERENCES `shifts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `employees_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `employees_work_location_id_foreign` FOREIGN KEY (`work_location_id`) REFERENCES `work_locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `employees_working_location_id_foreign` FOREIGN KEY (`working_location_id`) REFERENCES `working_locations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
